package com.nexodb.android;

import com.nexodb.db.*;
import org.json.*;
import java.sql.*;
import java.nio.file.*;
import java.util.*;

/** Database tools share the tested desktop services and their SQL validation. */
final class MobileTools {
    private final MobileBackend app;private record Design(JdbcSession owner,MysqlTableDesign.Snapshot snapshot){}
    private final Map<String,Design> designs=new HashMap<>();private final Map<String,CsvImportService.Preview> csv=new HashMap<>();
    MobileTools(MobileBackend app){this.app=app;}
    Object call(String method,JSONObject p)throws Exception{return switch(method){
        case "search"->search(p);
        case "design.get"->design(p.getString("database"),p.getString("table"));
        case "design.preview"->designSql(p);
        case "design.apply"->{String sql=designSql(p);Design base=approved(p);if(sql.isBlank())yield design(base.snapshot.database(),base.snapshot.table());app.authorize("Guardar estructura",sql);MysqlTableDesign.apply(app.session(),base.snapshot,sql);designs.remove(p.getString("id"));yield design(base.snapshot.database(),base.snapshot.table());}
        case "relations"->{var s=app.session();String database=p.getString("database");JSONArray values=new JSONArray(),tables=p.getJSONArray("tables");for(int i=0;i<tables.length();i++)for(var key:ForeignKeyDefinition.read(s.connection(),s.profile().type(),database,tables.getString(i)))values.put(MobileJson.value(key));yield values;}
        case "foreign.sql"->{List<ForeignKeyDefinition.ColumnPair> pairs=new ArrayList<>();JSONArray values=p.getJSONArray("columns");for(int i=0;i<values.length();i++)pairs.add(new ForeignKeyDefinition.ColumnPair(values.getJSONObject(i).getString("local"),values.getJSONObject(i).getString("referenced")));var key=new ForeignKeyDefinition(p.getString("database"),p.getString("table"),p.getString("name"),p.getString("parentDatabase"),p.getString("parentTable"),pairs,p.optString("onDelete","RESTRICT"),p.optString("onUpdate","RESTRICT"));yield key.createSql(app.session().connection().getMetaData().getIdentifierQuoteString());}
        case "backup.objects"->SqlBackupService.objects(app.session().connection(),p.getString("database"));
        case "backup"->backup(p);
        case "restore.review"->SqlImportService.analyze(app.documents.file(p.getString("handle")),new SqlTransferControl());
        case "restore"->restore(p);
        case "csv.review"->{var preview=CsvImportService.preview(app.documents.file(p.getString("handle")),p.optString("delimiter",",").charAt(0),p.optBoolean("header",true));String id=UUID.randomUUID().toString();csv.put(id,preview);yield new JSONObject().put("id",id).put("preview",MobileJson.value(preview));}
        case "csv.import"->importCsv(p);
        case "compare.schema"->compareSchema(p);
        default->throw new IllegalArgumentException("Acción no disponible: "+method);
    };}
    private Object search(JSONObject p)throws Exception{
        var s=app.session();String database=p.getString("database"),text=p.getString("text"),quote=s.connection().getMetaData().getIdentifierQuoteString();var schema=SchemaMetadataReader.read(s,database);Set<String> selected=new HashSet<>();JSONArray names=p.optJSONArray("tables");if(names!=null)for(int i=0;i<names.length();i++)selected.add(names.getString(i));JSONArray result=new JSONArray();SqlTransferControl control=new SqlTransferControl();app.transfer=control;
        try{for(var table:schema.objects().values())if(table.type().equals("TABLE")&&(selected.isEmpty()||selected.contains(table.name()))){control.check();app.activity.progress("Buscando en "+table.name());List<String> columns=table.columns().values().stream().filter(c->!c.type().toUpperCase(Locale.ROOT).matches(".*(BLOB|BINARY|BYTEA|IMAGE|GEOMETRY).*" )).map(SchemaMetadataReader.ColumnDef::name).toList();if(columns.isEmpty())continue;var condition=DataSearch.condition(s.profile().type(),quote,columns,text);String base="SELECT * FROM "+VisualQuery.qualified(database,table.name(),quote)+" WHERE ";try(PreparedStatement statement=s.connection().prepareStatement(base+condition.sql())){control.active(statement);statement.setMaxRows(101);for(int i=0;i<condition.parameters().size();i++)statement.setString(i+1,condition.parameters().get(i));int count=0;try(ResultSet rows=statement.executeQuery()){while(rows.next()){control.check();count++;}}if(count>0)result.put(new JSONObject().put("table",table.name()).put("count",count>100?"100+":String.valueOf(count)).put("sql",base+DataSearch.inline(s.profile().type(),condition)+";"));}catch(SQLException error){result.put(new JSONObject().put("table",table.name()).put("error",error.getMessage()));}finally{control.active(null);}}return result;}finally{app.transfer=null;}
    }
    private Object design(String database,String table)throws Exception{var snapshot=MysqlTableDesign.read(app.session(),database,table);String id=UUID.randomUUID().toString();designs.put(id,new Design(app.session(),snapshot));return new JSONObject().put("id",id).put("snapshot",MobileJson.value(snapshot));}
    private Design approved(JSONObject p)throws Exception{Design base=designs.get(p.getString("id"));if(base==null||base.owner!=app.session())throw new IllegalArgumentException("La estructura pertenece a otra conexión o cambió. Actualízala antes de guardar.");return base;}
    private String designSql(JSONObject p)throws Exception{
        var base=approved(p).snapshot;List<MysqlTableDesign.ColumnChange> columns=new ArrayList<>();List<MysqlTableDesign.IndexChange> indexes=new ArrayList<>();List<MysqlTableDesign.KeyChange> keys=new ArrayList<>();
        JSONArray cs=p.getJSONArray("columns"),ix=p.getJSONArray("indexes"),fk=p.getJSONArray("keys");
        for(int i=0;i<cs.length();i++){JSONObject r=cs.getJSONObject(i),v=r.getJSONObject("value");columns.add(new MysqlTableDesign.ColumnChange((String)MobileJson.nullable(r,"original"),new MysqlTableDesign.Column(v.getString("name"),v.getString("type"),v.optString("length"),v.optBoolean("notNull"),v.optBoolean("unsigned"),v.optBoolean("autoIncrement"),v.optBoolean("zerofill"),v.optString("defaultSql"),v.optString("onUpdate"),v.optString("comment"),v.optString("generated"),v.optString("expression"),v.optString("charset"),v.optString("collation"),v.optBoolean("invisible"),v.optString("unsupported"))));}
        for(int i=0;i<ix.length();i++){JSONObject r=ix.getJSONObject(i),v=r.getJSONObject("value");List<MysqlTableDesign.IndexColumn> parts=new ArrayList<>();JSONArray ps=v.getJSONArray("columns");for(int j=0;j<ps.length();j++){JSONObject part=ps.getJSONObject(j);parts.add(new MysqlTableDesign.IndexColumn(part.getString("name"),part.optString("prefix"),part.optString("order","ASC")));}indexes.add(new MysqlTableDesign.IndexChange((String)MobileJson.nullable(r,"original"),new MysqlTableDesign.Index(v.getString("name"),v.getString("kind"),parts,v.optString("method","BTREE"),v.optString("comment"),v.optBoolean("invisible"),v.optString("unsupported"))));}
        for(int i=0;i<fk.length();i++){JSONObject r=fk.getJSONObject(i),v=r.getJSONObject("value");List<ForeignKeyDefinition.ColumnPair> pairs=new ArrayList<>();JSONArray ps=v.getJSONArray("columns");for(int j=0;j<ps.length();j++){JSONObject part=ps.getJSONObject(j);pairs.add(new ForeignKeyDefinition.ColumnPair(part.getString("local"),part.getString("referenced")));}keys.add(new MysqlTableDesign.KeyChange((String)MobileJson.nullable(r,"original"),new ForeignKeyDefinition(base.database(),base.table(),v.getString("name"),v.optString("parentDatabase",base.database()),v.getString("parentTable"),pairs,v.optString("onDelete","RESTRICT"),v.optString("onUpdate","RESTRICT"))));}
        JSONObject o=p.getJSONObject("options");return MysqlTableDesign.plan(base,columns,indexes,keys,new MysqlTableDesign.Options(o.getString("engine"),o.getString("charset"),o.getString("collation"),o.optString("comment"),o.optString("autoIncrement"),o.getString("rowFormat"),o.optString("averageRowLength"),o.optString("maxRows"),o.optString("minRows"),o.optString("checksum"),o.optString("delayKeyWrite")));
    }
    private Object backup(JSONObject p)throws Exception{
        var s=app.session();String database=p.getString("database");List<SqlBackupService.ObjectInfo> selected=SqlBackupService.objects(s.connection(),database);Set<String> names=new HashSet<>();JSONArray values=p.getJSONArray("objects");for(int i=0;i<values.length();i++)names.add(values.getString(i));selected=selected.stream().filter(o->names.contains(o.kind().name()+":"+o.name())).toList();if(selected.isEmpty())throw new IllegalArgumentException("Selecciona objetos para respaldar.");if(!app.activity.ask("Crear respaldo SQL",database+"\n"+selected.size()+" objetos. ¿Continuar?"))throw MobileBackend.cancelled();
        Path file=Files.createTempFile(app.activity.getCacheDir().toPath(),"backup-",".sql");SqlTransferControl control=new SqlTransferControl();app.transfer=control;
        try{var options=new SqlBackupService.Options(SqlBackupService.Mode.valueOf(p.optString("mode","STRUCTURE_AND_DATA")),p.optBoolean("createDatabase",true),p.optBoolean("drop"),p.optBoolean("foreignKeys",true),p.optBoolean("consistent",true),p.optBoolean("omitDefiner",true));var report=SqlBackupService.write(s.connection(),s.profile().type(),database,selected,options,file,control,v->app.activity.progress(v.object()+" · "+v.rows()+" filas"));app.documents.export(file,database+"-"+java.time.LocalDate.now()+".sql");return report;}finally{app.transfer=null;Files.deleteIfExists(file);}
    }
    private Object restore(JSONObject p)throws Exception{
        var reviewed=SqlImportService.analyze(app.documents.file(p.getString("handle")),new SqlTransferControl());app.authorize("Importar SQL",reviewed.statements()+" sentencias · "+reviewed.destructive()+" operaciones destructivas\nDestino: "+p.getString("database")+"\n\n"+reviewed.preview());SqlTransferControl control=new SqlTransferControl();app.transfer=control;
        try{return SqlImportService.restore(app.session().connection(),reviewed,new SqlImportService.Options(p.getString("database"),p.optBoolean("create"),p.optBoolean("preserve"),p.optBoolean("omitDefiner",true)),control,v->app.activity.progress(v.completed()+" / "+v.total()+" sentencias"));}finally{app.transfer=null;}
    }
    private Object importCsv(JSONObject p)throws Exception{
        var preview=csv.get(p.getString("id"));if(preview==null)throw new IllegalArgumentException("Vuelve a revisar el CSV.");String database=p.getString("database"),table=p.getString("table"),quote=app.session().connection().getMetaData().getIdentifierQuoteString();Map<String,Integer> types=new HashMap<>();boolean catalogs=SchemaMetadataReader.catalogNamespace(app.session().profile().type());try(ResultSet r=app.session().connection().getMetaData().getColumns(catalogs?database:null,catalogs?null:database,table,"%")){while(r.next())types.put(r.getString("COLUMN_NAME"),r.getInt("DATA_TYPE"));}
        List<CsvImportService.Mapping> mapping=new ArrayList<>();JSONArray values=p.getJSONArray("mapping");for(int i=0;i<values.length();i++){JSONObject value=values.getJSONObject(i);String target=value.getString("target");if(!types.containsKey(target))throw new IllegalArgumentException("Columna no disponible: "+target);mapping.add(new CsvImportService.Mapping(value.getInt("source"),new CsvImportService.Column(target,types.get(target))));}
        String target=VisualQuery.qualified(database,table,quote);app.authorize("Importar CSV",target+"\nSe insertarán filas usando las columnas seleccionadas.");SqlTransferControl control=new SqlTransferControl();app.transfer=control;try{return CsvImportService.importRows(app.session().connection(),preview,new CsvImportService.Options(target,mapping,p.optString("nullToken","NULL"),p.optBoolean("emptyNull")),control,count->app.activity.progress(count+" filas"));}finally{app.transfer=null;}
    }
    private Object compareSchema(JSONObject p)throws Exception{
        JdbcSession left=app.sessions.get(p.getString("source")),right=app.sessions.get(p.getString("target"));if(left==null||right==null)throw new IllegalArgumentException("Conecta ambos perfiles antes de comparar.");var pair=SchemaMetadataReader.readPair(left,p.getString("sourceDatabase"),right,p.getString("targetDatabase"));JSONArray differences=new JSONArray();Set<String> names=new TreeSet<>(pair.source().objects().keySet());names.addAll(pair.target().objects().keySet());Set<String> selected=new HashSet<>();JSONArray selection=p.optJSONArray("objects");if(selection!=null)for(int i=0;i<selection.length();i++)selected.add(selection.getString(i));for(String name:names){if(!selected.isEmpty()&&!selected.contains(name))continue;var a=pair.source().objects().get(name);var b=pair.target().objects().get(name);differences.put(new JSONObject().put("key",name).put("name",a!=null?a.name():b.name()).put("status",a==null?"Solo en destino":b==null?"Solo en origen":a.columns().equals(b.columns())?"Igual":"Diferente").put("source",MobileJson.value(a)).put("target",MobileJson.value(b)));}return differences;
    }
}
